@layer theme, base, components, utilities;

@layer components {
  .icon {
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    overflow: visible;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* A chevron is one size everywhere (--ui-icon-chevron), a step under the
     icons around it. */
  .icon[data-icon^="chevron"] {
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
  }

  /* A disclosure chevron that points right and opens downward turns a
     quarter turn (data-turn="open"): changing axis, a morph between the two
     shapes reads as the arrow coming apart, so this one rotates, on the glide
     curve with no overshoot. Down/up chevrons morph instead. */
  .icon.icon[data-turn] {
    /* Doubled class: outranks a component's own `transition` on its chevron
       (usually its hover color), so both are listed here. */
    transition:
      rotate var(--ui-dur-base) var(--ui-ease-glide),
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .icon[data-turn="open"] {
    rotate: 90deg;
  }

  :is([dir="rtl"]) .icon[data-turn] {
    scale: -1 1;
  }

  :is([dir="rtl"]) .icon[data-turn="open"] {
    rotate: -90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .icon.icon[data-turn] {
      transition: color var(--ui-dur-instant) var(--ui-ease-color);
    }
  }

  /* The gap (3) must exceed any path plus margins so the dash never repeats. */
  .stroke {
    stroke-dasharray: var(--len, 1) 3;
    stroke-dashoffset: var(--on, 0);
    transform-box: fill-box;
    transform-origin: center;
    /* --icon-morph-ease: set to --ui-ease-glide where a morph should land
       without overshoot (a result, not a toggle). */
    transition:
      d var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dasharray var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dashoffset var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      rotate var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that leaves (copy's sheets as the check arrives) gets out of
     the way: it erases, fades and draws in slightly, all quickly, so the two
     shapes never tangle in the same spot. */
  .stroke[data-off] {
    stroke-dashoffset: var(--off, 1.3);
    opacity: 0;
    scale: 0.85;
    transition:
      stroke-dashoffset var(--ui-dur-fast) var(--ui-ease-exit),
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      scale var(--ui-dur-fast) var(--ui-ease-exit),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that arrives waits a beat for the old one to clear, then draws
     on in one clean pass. */
  .stroke[data-enter] {
    transition:
      stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw) calc(var(--ui-dur-instant) * 0.6),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* Two strokes that meet end to end at rest (copy's sheet and rim): the
     moving one lands without overshoot, so the seam never opens, and the
     other erases in place along its path instead of fading and shrinking, so
     copy → check reads as one line opening at its corner. */
  .stroke.seam:not([data-enter]) {
    transition:
      d var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dasharray var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dashoffset var(--ui-dur-glide) var(--ui-ease-glide),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .stroke.seam[data-off] {
    opacity: 1;
    scale: none;
    transition:
      stroke-dashoffset var(--ui-dur-instant) var(--ui-ease-draw),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @starting-style {
    .icon[data-ready] .stroke[data-enter] {
      stroke-dashoffset: var(--off, 1.3);
    }
  }

  .block {
    stroke-width: 4;
  }

  /* Mask copy of a cut stroke: gaps the other strokes on both sides of it. */
  .cut {
    stroke: black;
    stroke-width: calc(var(--ui-icon-stroke, 1.5) * 3);
  }

  /* ---------- Parent hover ---------- */

  @media (hover: hover) {
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .lid {
      translate: 0 -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .out {
      translate: 1px -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .drop {
      translate: 0 1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .forward {
      translate: 1px 0;
    }
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .lid {
    translate: 0 -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .out {
    translate: 1px -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .drop {
    translate: 0 1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .forward {
    translate: 1px 0;
  }

  @media (prefers-reduced-motion: reduce) {
    .stroke,
    .stroke[data-off],
    .stroke[data-enter],
    .stroke.seam:not([data-enter]),
    .stroke.seam[data-off] {
      transition: none;
    }
  }
}

"use client";

import { useId, useState, type ComponentProps, type CSSProperties } from "react";
import styles from "./icons.module.css";

/*
 * Each icon is a few keyed strokes on a 16px grid. When `name` changes, a key
 * in both icons morphs (`d` only interpolates when the commands match); old-only
 * keys retract, new-only keys draw in. Give pairs shared keys so little ink moves.
 * Strokes use pathLength 1; a window f/t must touch a path end so it can retract.
 */

type Stroke = {
  d: string;
  /** Visible window along the path, 0–1. One end must touch the path's end. */
  f?: number;
  t?: number;
  /** Cut a gap in the other strokes along this line. */
  cut?: boolean;
  /** Draw as a solid rounded block. */
  block?: boolean;
  /** Degrees, about its own midpoint. */
  rot?: number;
  /** Meets another stroke end to end at rest: morphs without overshoot and
   *  erases in place (no fade or shrink) so the seam never shows. */
  seam?: boolean;
  /** Nudges 1px while the parent control is hovered or focused. */
  fx?: "lid" | "drop" | "out" | "forward";
};

/* Copy's front sheet is two strokes that meet end to end. `sheet` is its left
   edge, bottom-left corner and bottom edge: turned 45° that corner is a check,
   so copy → check moves those points while `rim` (the rest of the square)
   erases from the bottom-right corner round to the top-left. */
const SHEET = {
  d: "M5.76 5.76 C5.43 6.09 5.25 6.54 5.25 7 L5.25 11.5 C5.25 12.47 6.03 13.25 7 13.25 L11.5 13.25",
  seam: true,
} satisfies Stroke;
const RIM = {
  d: "M5.76 5.76A1.75 1.75 0 0 1 7 5.25H11.5A1.75 1.75 0 0 1 13.25 7V11.5A1.75 1.75 0 0 1 11.5 13.25",
  seam: true,
} satisfies Stroke;
// The same commands as SHEET; the corner is a short curve so it can come from the rounded one.
const CHECK = {
  d: "M3.75 8.25 C3.96 8.46 4.17 8.67 4.38 8.88 L6.4 10.9 C6.75 11.25 6.75 11.25 7.08 10.87 L12.25 5",
  seam: true,
} satisfies Stroke;
const BACK_SHEET = "M9.25 2.75H4.5A1.75 1.75 0 0 0 2.75 4.5V9.25";
const EYE = "M1.75 8C3.1 5.1 5.4 3.5 8 3.5s4.9 1.6 6.25 4.5C12.9 10.9 10.6 12.5 8 12.5S3.1 10.9 1.75 8Z";
const PUPIL = "M6 8a2 2 0 1 0 4 0a2 2 0 1 0-4 0";
const RING = "M14.25 8a6.25 6.25 0 1 1-12.5 0a6.25 6.25 0 1 1 12.5 0";
const CHANGE_FRAME = "M2.75 5.75a3 3 0 0 1 3-3h4.5a3 3 0 0 1 3 3v4.5a3 3 0 0 1-3 3h-4.5a3 3 0 0 1-3-3Z";

const CHEVRON_V = ["M2.87 8 L8.88 8", "M7.12 8 L13.13 8"] as const;
const CHEVRON_H = ["M5 5.875 L11 5.875", "M5 10.125 L11 10.125"] as const;

const ARROW_UP = {
  s: { d: "M8 3.25 L8 12.75" },
  h1: { d: "M8 3.25 L3.75 7.5" },
  h2: { d: "M8 3.25 L12.25 7.5" },
};

const ICONS = {
  eye: { eye: { d: EYE }, pupil: { d: PUPIL } },
  "eye-off": { eye: { d: EYE }, pupil: { d: PUPIL }, slash: { d: "M2.75 2.75 L13.25 13.25", cut: true } },
  copy: { back: { d: BACK_SHEET }, sheet: SHEET, rim: RIM },
  check: { sheet: CHECK },
  duplicate: { back: { d: BACK_SHEET }, sheet: SHEET, rim: RIM, add: { d: "M9.25 7.5v3.5M7.5 9.25h3.5" } },
  plus: { a: { d: "M3.25 8 L12.75 8" }, b: { d: "M8 12.75 L8 3.25" } },
  close: { a: { d: "M4.75 4.75 L11.25 11.25" }, b: { d: "M4.75 11.25 L11.25 4.75" } },
  minus: { a: { d: "M3.25 8 L12.75 8" } },
  menu: {
    a: { d: "M2.75 4.75 L13.25 4.75" },
    m: { d: "M2.75 8 L13.25 8" },
    b: { d: "M2.75 11.25 L13.25 11.25" },
  },
  "arrow-up": ARROW_UP,
  send: ARROW_UP,
  "arrow-down": {
    s: { d: "M8 3.25 L8 12.75" },
    h1: { d: "M8 12.75 L3.75 8.5" },
    h2: { d: "M8 12.75 L12.25 8.5" },
  },
  "arrow-left": {
    s: { d: "M3.25 8 L12.75 8" },
    h1: { d: "M3.25 8 L7.5 3.75" },
    h2: { d: "M3.25 8 L7.5 12.25" },
  },
  "arrow-right": {
    s: { d: "M3.25 8 L12.75 8", fx: "forward" },
    h1: { d: "M12.75 8 L8.5 3.75", fx: "forward" },
    h2: { d: "M12.75 8 L8.5 12.25", fx: "forward" },
  },
  "chevron-up": { a: { d: CHEVRON_V[0], rot: -45 }, b: { d: CHEVRON_V[1], rot: 45 } },
  "chevron-down": { a: { d: CHEVRON_V[0], rot: 45 }, b: { d: CHEVRON_V[1], rot: -45 } },
  "chevron-left": { a: { d: CHEVRON_H[0], rot: -45 }, b: { d: CHEVRON_H[1], rot: 45 } },
  "chevron-right": { a: { d: CHEVRON_H[0], rot: 45 }, b: { d: CHEVRON_H[1], rot: -45 } },
  stop: { block: { d: "M6 6 L10 6 L10 10 L6 10 Z", block: true } },
  mic: {
    capsule: { d: "M8 2.25a2.25 2.25 0 0 0-2.25 2.25v3.25a2.25 2.25 0 0 0 4.5 0V4.5A2.25 2.25 0 0 0 8 2.25Z" },
    cradle: { d: "M3.75 7.5a4.25 4.25 0 0 0 8.5 0" },
    stand: { d: "M8 11.75v2" },
  },
  // Pause's right bar is drawn with play's commands (a line through its own
  // midpoint), so it bends out into the triangle's point while the left bar
  // stays put: one motion, nothing erased or drawn in. On the glide (seam),
  // so the bar never bows past straight on its way back.
  play: {
    l: { d: "M5.25 12.5 L5.25 3.5", seam: true },
    t: { d: "M5.25 3.5 L12.25 8 L5.25 12.5", seam: true },
  },
  pause: {
    l: { d: "M5.75 12.25 L5.75 3.75", seam: true },
    t: { d: "M10.25 3.75 L10.25 8 L10.25 12.25", seam: true },
  },
  search: {
    ring: { d: "M11.75 7.25a4.5 4.5 0 1 1-9 0a4.5 4.5 0 1 1 9 0" },
    handle: { d: "M10.5 10.5 L13.25 13.25" },
  },
  link: {
    l1: { d: "M6.75 9.25 9.25 6.75" },
    l2: { d: "M7.4 4.6 8.2 3.8a2.65 2.65 0 0 1 3.75 3.75l-.8.8" },
    l3: { d: "M8.6 11.4 7.8 12.2a2.65 2.65 0 0 1-3.75-3.75l.8-.8" },
  },
  download: {
    arrow: { d: "M8 2.75v7M4.75 6.75 8 10l3.25-3.25", fx: "drop" },
    base: { d: "M3 13.25h10" },
  },
  trash: {
    lid: { d: "M2.75 4.5h10.5M6.25 4.5V3.5a1 1 0 0 1 1-1h1.5a1 1 0 0 1 1 1v1", fx: "lid" },
    can: { d: "M4.25 4.5l.6 8a1.35 1.35 0 0 0 1.35 1.25h3.6a1.35 1.35 0 0 0 1.35-1.25l.6-8" },
  },
  external: { out: { d: "M4.75 11.25 11.25 4.75M5.75 4.75h5.5v5.5", fx: "out" } },
  upload: {
    arrow: { d: "M8 10.25v-7.5M4.75 6 8 2.75 11.25 6", fx: "lid" },
    base: { d: "M3 13.25h10" },
  },
  file: {
    sheet: { d: "M4.25 3.75A1.5 1.5 0 0 1 5.75 2.25h3.5l3.5 3.5v6.5a1.5 1.5 0 0 1-1.5 1.5h-5.5a1.5 1.5 0 0 1-1.5-1.5Z" },
    fold: { d: "M9.25 2.5v3.25h3.25" },
  },
  /* The arc runs into a short straight lead, and the head is a clean
     corner at its end, so the two never pile up into a blob. */
  retry: {
    arc: { d: "M13.5 8a5.5 5.5 0 1 1-5.5-5.5c1.54 0 3.01.61 4.12 1.67L13.5 5.5" },
    head: { d: "M13.5 2.44 L13.5 5.5 L10.44 5.5" },
  },
  calendar: {
    body: { d: "M2.75 5.25A1.75 1.75 0 0 1 4.5 3.5h7a1.75 1.75 0 0 1 1.75 1.75v6.5a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    bar: { d: "M2.75 7.25 L13.25 7.25" },
    pins: { d: "M5.5 2.25v2.5M10.5 2.25v2.5" },
  },
  /* Dots are near-zero-length strokes drawn by the round cap. */
  info: {
    ring: { d: RING },
    stem: { d: "M8 7.25 L8 11.25" },
    dot: { d: "M8 4.75 L8 4.76" },
  },
  alert: {
    ring: { d: RING },
    stem: { d: "M8 4.75 L8 8.5" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  "check-circle": {
    ring: { d: RING },
    tick: { d: "M5.5 8.25 L7.25 10 L10.5 6.25" },
  },
  /* Three dots in a row: the overflow menu on a row or a card. */
  more: {
    a: { d: "M3.75 8 L3.76 8" },
    dot: { d: "M8 8 L8.01 8" },
    b: { d: "M12.25 8 L12.26 8" },
  },
  pencil: {
    body: { d: "M10.25 3.25a1.5 1.5 0 0 1 2.12 0l.38.38a1.5 1.5 0 0 1 0 2.12L6.5 12 3 13l1-3.5Z" },
    edge: { d: "M9.25 4.25 L11.75 6.75" },
  },
  /* A panel with its side column: show or hide a sidebar. */
  sidebar: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M6.25 2.75 L6.25 13.25" },
  },
  warning: {
    tri: { d: "M6.92 3.1a1.25 1.25 0 0 1 2.16 0l5 8.65a1.25 1.25 0 0 1-1.08 1.875H3a1.25 1.25 0 0 1-1.08-1.875Z" },
    stem: { d: "M8 6.25 L8 9" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  /* App chrome: places, tools and panes an app's frame needs. Static. */
  home: {
    roof: { d: "M2.25 7.25 8 2.5l5.75 4.75" },
    body: { d: "M3.75 6v6.25a1 1 0 0 0 1 1h6.5a1 1 0 0 0 1-1V6" },
    door: { d: "M6.75 13.25v-3h2.5v3" },
  },
  compose: {
    frame: { d: "M13.25 8.75v3a1.5 1.5 0 0 1-1.5 1.5h-7.5a1.5 1.5 0 0 1-1.5-1.5v-7.5a1.5 1.5 0 0 1 1.5-1.5h3" },
    pen: { d: "M11.35 2.65a1.35 1.35 0 0 1 1.9 1.9L8.6 9.2l-2.35.55.55-2.35Z" },
  },
  settings: {
    rails: { d: "M2.75 4.5h4.5M10.25 4.5h3M2.75 11.5h1.5M7.25 11.5h6" },
    knobs: { d: "M8.75 3v3M5.75 10v3" },
  },
  help: {
    ring: { d: RING },
    hook: { d: "M6.25 6.4a1.8 1.8 0 1 1 2.55 1.65c-.5.25-.8.6-.8 1.1v.25" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  clock: {
    ring: { d: RING },
    hands: { d: "M8 4.75v3.5l2.25 1.5" },
  },
  share: {
    arrow: { d: "M8 9.75v-7M5.25 5.25 8 2.5l2.75 2.75", fx: "lid" },
    tray: { d: "M4.75 7.5h-.5a1.5 1.5 0 0 0-1.5 1.5v2.75a1.5 1.5 0 0 0 1.5 1.5h7.5a1.5 1.5 0 0 0 1.5-1.5V9a1.5 1.5 0 0 0-1.5-1.5h-.5" },
  },
  folder: {
    body: { d: "M2.75 4.75a1.5 1.5 0 0 1 1.5-1.5h2.3l1.4 1.5h3.8a1.5 1.5 0 0 1 1.5 1.5v5.5a1.5 1.5 0 0 1-1.5 1.5h-7.5a1.5 1.5 0 0 1-1.5-1.5Z" },
  },
  paperclip: {
    clip: { d: "M12.75 7.25 8.1 11.9a2.9 2.9 0 0 1-4.1-4.1l4.85-4.85a1.85 1.85 0 0 1 2.6 2.6L6.6 10.4a.8.8 0 0 1-1.1-1.1l4.35-4.35" },
  },
  at: {
    ring: { d: "M10.5 8v.9a1.85 1.85 0 0 0 3.7 0V8a6.2 6.2 0 1 0-2.45 4.95" },
    core: { d: "M10.5 8a2.5 2.5 0 1 1-5 0a2.5 2.5 0 1 1 5 0" },
  },
  list: {
    lines: { d: "M6.75 4.5h6.5M6.75 8h6.5M6.75 11.5h6.5" },
    dots: { d: "M3.25 4.5h.01M3.25 8h.01M3.25 11.5h.01" },
  },
  terminal: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Shared field parts to compose. */

  .field {
    display: grid;
    /* The field's width, not its input's: an input's default size (about 20
       characters) would otherwise push a narrow form sideways. */
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ui-space-2);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .shell {
    --edge: var(--ui-border-strong);
    --edge-width: var(--ui-hairline);
    --shell-inset: calc((var(--ui-control-md) - var(--ui-control-sm)) / 2);
    position: relative;
    height: var(--ui-control-md);
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition: box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .shell:hover:not(:focus-within, [data-invalid], [data-disabled], [data-open]) {
      --edge: var(--ui-field-focus);
    }
  }

  .shell:focus-within,
  .shell[data-open] {
    --edge: var(--ui-field-focus);
    --edge-width: 1px;
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition-duration: 0s;
  }

  .shell[data-open] {
    transition-duration: var(--ui-dur-instant);
  }

  .shell[data-invalid] {
    --edge: var(--ui-danger);
  }

  .shell[data-disabled] {
    opacity: 0.5;
  }

  .bare {
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
  }

  .bare::placeholder {
    color: var(--ui-subtle);
  }

  .bare:disabled {
    cursor: default;
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .bare {
      font-size: var(--ui-text-touch);
    }
  }

  /* Inset button. Set its radius where it sits (outer radius less the inset). */
  .inset {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: relative;
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--ui-control-sm);
    height: var(--ui-control-sm);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--shell-inset, 4px));
    background: none;
    color: var(--ui-muted);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .inset::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .inset > * {
    position: relative;
  }

  @media (hover: hover) {
    .inset:hover:not(:disabled, [aria-disabled]) {
      color: var(--ui-foreground);
    }
    .inset:hover:not(:disabled, [aria-disabled])::before {
      background: var(--ui-fill);
    }
  }

  .inset:active:not(:disabled, [aria-disabled]) {
    color: var(--ui-foreground);
  }

  .inset:active:not(:disabled, [aria-disabled])::before {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .inset:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
    color: var(--ui-foreground);
  }

  .inset:disabled,
  .inset[aria-disabled] {
    cursor: default;
  }

  /* 32px to look at, 40px to hit. */
  @media (pointer: coarse) {
    .inset::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  .message {
    display: grid;
    min-height: var(--ui-leading-md);
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .errorIcon {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
  }

  .error[data-shown] .errorText {
    animation: field-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes field-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .inset:active:not(:disabled, [aria-disabled])::before {
      scale: none;
    }
    .error[data-shown] .errorText {
      animation: none;
    }
  }
}

"use client";

import { useState } from "react";
import { Icon } from "../icons/icons";
import styles from "./field.module.css";

type FieldMessageProps = {
  id: string;
  hint?: string | null;
  error?: string | null;
};

/** Hint or error; the hidden one leaves the description and live region. */
export function FieldMessage({ id, hint, error }: FieldMessageProps) {
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  return (
    <p id={id} className={styles.message} aria-live="polite">
      {hint && (
        <span className={styles.hint} data-shown={!error || undefined}>
          {hint}
        </span>
      )}
      {lastError && (
        <span className={styles.error} data-shown={error ? true : undefined}>
          <Icon name="alert" className={styles.errorIcon} />
          <span key={lastError} className={styles.errorText}>
            {lastError}
          </span>
        </span>
      )}
    </p>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

@property --list-start {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@property --list-end {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

.list {
  composes: fade;
}

.label {
  composes: wrap from "../text/text.module.css";
}

.description {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* The Base UI positioner. It only holds the place and is never scaled;
     .panel (the popup) animates. */
  .popup {
    z-index: 50;
    width: var(--listbox-width, max-content);
    max-width: calc(100vw - 16px);
    outline: none;
  }

  .panel {
    --list-pad: var(--ui-space-1);
    --panel-radius: var(--ui-radius-md);
    display: flex;
    flex-direction: column;
    max-height: var(--available-height, none);
    overflow: hidden;
    border-radius: var(--panel-radius);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-floating);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    outline: none;
    user-select: none;
    transform-origin: var(--transform-origin);
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .panel[data-starting-style],
  .panel[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .panel[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  /* Scroll-driven edge fade; data-fits is set by useHighlight. Other components compose this. */
  .fade {
    --list-fade: var(--ui-space-4);
    scroll-padding-block: var(--list-fade);
  }

  @supports (animation-timeline: scroll()) {
    .fade {
      mask-image: linear-gradient(
        to bottom,
        rgb(0 0 0 / var(--list-start)),
        black var(--list-fade),
        black calc(100% - var(--list-fade)),
        rgb(0 0 0 / var(--list-end))
      );
      animation:
        list-start linear both,
        list-end linear both;
      animation-timeline: scroll(self block), scroll(self block);
      animation-range:
        0 var(--list-fade),
        calc(100% - var(--list-fade)) 100%;
    }

    .fade[data-fits] {
      animation: none;
    }
  }

  @keyframes list-start {
    from {
      --list-start: 1;
    }
    to {
      --list-start: 0;
    }
  }

  @keyframes list-end {
    from {
      --list-end: 0;
    }
    to {
      --list-end: 1;
    }
  }

  .list {
    position: relative;
    flex: 0 1 auto;
    min-height: 0;
    max-height: min(300px, calc(100dvh - 160px));
    padding: var(--list-pad);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .list:not(:has([role="option"])) {
    display: none;
  }

  .highlight {
    position: absolute;
    top: 0;
    left: var(--list-pad);
    right: var(--list-pad);
    border-radius: calc(var(--panel-radius) - var(--list-pad));
    background: var(--ui-fill-strong);
    opacity: 0;
    pointer-events: none;
    transition:
      translate var(--ui-dur-snap) var(--ui-ease-snap),
      height var(--ui-dur-glide) var(--ui-ease-glide),
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .highlight[data-visible] {
    opacity: 1;
  }

  .highlight[data-jump] {
    transition-property: opacity, background-color;
  }

  .list:has(.option:active:not([data-disabled])) > .highlight {
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
    transition-duration: var(--ui-dur-press);
  }

  .option {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* Inline: a full row pad, never less than the row's radius, so the text
       clears the curve. */
    padding: var(--ui-space-2) var(--ui-pad-row);
    border-radius: calc(var(--panel-radius) - var(--list-pad));
    outline: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  .option[data-disabled] {
    opacity: 0.5;
    cursor: default;
  }

  .lead {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: 16px;
    height: var(--ui-leading-md);
    color: var(--ui-muted);
  }

  .text {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .check {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: 16px;
    height: 16px;
    visibility: hidden;
  }

  .option[data-selected] .check {
    visibility: visible;
  }

  .status {
    margin: 0;
    /* Its text lines up with the options' text. */
    padding: var(--ui-space-3) calc(var(--list-pad) + var(--ui-pad-row));
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .list:has([role="option"]) + .status {
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  @media (prefers-reduced-motion: reduce) {
    .panel {
      transition: none;
    }
    .panel {
      scale: none;
    }
    .highlight {
      transition-property: opacity, background-color;
    }
  }
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState } from "react";

/**
 * Slides one highlight bar to the row Base UI marks `data-highlighted`, and
 * marks a list that fits without scrolling (`data-fits`, for the edge fade).
 *
 * Put `listRef` on the scrolling list and `barRef` on a span that is the
 * list's first child. Base UI keeps the highlighted row in view itself.
 * With `centerSelected`, the chosen row (`data-selected`) starts in the
 * middle of the list each time it opens.
 */
export function useHighlight({ centerSelected = false }: { centerSelected?: boolean } = {}) {
  const listNode = useRef<HTMLElement | null>(null);
  const barRef = useRef<HTMLSpanElement>(null);
  // Bumped when the list mounts or unmounts: Base UI renders it only while open.
  const [mounts, setMounts] = useState(0);
  const listRef = useCallback((node: HTMLElement | null) => {
    listNode.current = node;
    setMounts((n) => n + 1);
  }, []);

  useLayoutEffect(() => {
    const list = listNode.current;
    const bar = barRef.current;
    if (!list || !bar) return;
    const state = { centered: !centerSelected };

    function update() {
      if (!list || !bar) return;
      // Once, when the list first has a height: the chosen row in the middle.
      if (!state.centered && list.clientHeight > 0) {
        state.centered = true;
        const chosen = list.querySelector<HTMLElement>("[data-selected]");
        if (chosen) list.scrollTop = chosen.offsetTop - (list.clientHeight - chosen.offsetHeight) / 2;
      }
      // Not scrollHeight: the bar's height transition can briefly overflow the list.
      const last = list.lastElementChild instanceof HTMLElement ? list.lastElementChild : null;
      const end = last ? last.offsetTop + last.offsetHeight + (parseFloat(getComputedStyle(list).paddingBottom) || 0) : 0;
      list.toggleAttribute("data-fits", end - list.clientHeight <= 1);

      const row = list.querySelector<HTMLElement>("[data-highlighted]");
      if (!row) {
        bar.removeAttribute("data-visible");
        return;
      }
      const jump = !bar.hasAttribute("data-visible");
      if (jump) bar.setAttribute("data-jump", "");
      bar.style.translate = `0 ${row.offsetTop}px`;
      bar.style.height = `${row.offsetHeight}px`;
      bar.setAttribute("data-visible", "");
      if (jump) {
        bar.getBoundingClientRect();
        bar.removeAttribute("data-jump");
      }
    }

    update();
    const mutations = new MutationObserver(update);
    mutations.observe(list, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: ["data-highlighted"],
    });
    const resize = new ResizeObserver(update);
    resize.observe(list);
    return () => {
      mutations.disconnect();
      resize.disconnect();
    };
  }, [mounts, centerSelected]);

  return { listRef, barRef, listNode };
}

@layer theme, base, components, utilities;

/* The real label, for screen readers and find-in-page. */
.label {
  composes: srOnly from "../text/text.module.css";
}

/* Block padding keeps descenders inside the mask. */
@property --morph-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  .root {
    position: relative;
    display: inline-flex;
    white-space: pre;
  }

  .row {
    --morph-to: right;
    position: relative;
    display: inline-flex;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  :is([dir="rtl"]) .row {
    --morph-to: left;
  }

  .row[data-morphing] {
    mask-image: linear-gradient(to var(--morph-to), #000 calc(100% - var(--morph-fade)), transparent);
  }

  /* A filter (the blur on arriving and leaving letters) paints only inside
     the element's box, and a glyph's descender hangs below a tight line box.
     The block padding grows each letter's box to hold its descenders; the
     negative margin gives the room back, so nothing moves. */
  .glyph {
    display: inline-block;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  .ghosts {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Sits where the letter sat: the row's block padding, held as the ghost's
     own padding so its blur has room for descenders too. */
  .ghost {
    position: absolute;
    top: 0;
    padding-block: 0.3em;
  }
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import styles from "./text-morph.module.css";

type Glyph = { key: string; char: string };
type Layout = { text: string; glyphs: Glyph[]; lefts: Map<string, number>; width: number };

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function split(text: string) {
  return segmenter ? Array.from(segmenter.segment(text), (s) => s.segment) : Array.from(text);
}

type Word = { start: number; end: number; text: string };

function words(chars: string[]): Word[] {
  const out: Word[] = [];
  let start = -1;
  chars.forEach((c, i) => {
    const space = /\s/.test(c);
    if (!space && start === -1) start = i;
    if (space && start !== -1) {
      out.push({ start, end: i, text: chars.slice(start, i).join("").toLowerCase() });
      start = -1;
    }
  });
  if (start !== -1) out.push({ start, end: chars.length, text: chars.slice(start).join("").toLowerCase() });
  return out;
}

/** Shared start and end letters: "Copy" → "Copied" keeps "Cop". */
function edges(a: string[], b: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) pairs.push([start, start++]);
  for (let k = 1; k <= Math.min(a.length, b.length) - start && a[a.length - k] === b[b.length - k]; k++) {
    pairs.push([a.length - k, b.length - k]);
  }
  return pairs;
}

/** Keys letters, reusing old keys for shared words and gap edges so they slide. */
function toGlyphs(prev: Glyph[] | null, text: string, generation: number): Glyph[] {
  // Same keys on the server and in the browser.
  const fresh = (i: number) => `${generation}:${i}`;
  const chars = split(text);
  if (!prev) return chars.map((char, i) => ({ key: fresh(i), char }));
  const keys: (string | null)[] = chars.map(() => null);
  const old = prev.map((g) => g.char);

  // Numbers match by place value, from the right.
  if (numeric(old.join("")) && numeric(text)) {
    for (let k = 1; k <= Math.min(old.length, chars.length); k++) {
      if (old[old.length - k] === chars[chars.length - k]) keys[chars.length - k] = prev[old.length - k].key;
    }
    return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
  }

  const oldWords = words(old);
  const used = new Set<number>();
  const anchors: { from: Word; to: Word }[] = [];
  for (const w of words(chars)) {
    const i = oldWords.findIndex((o, k) => !used.has(k) && o.text === w.text);
    if (i === -1) continue;
    used.add(i);
    anchors.push({ from: oldWords[i], to: w });
    for (let k = 0; k < w.end - w.start; k++) {
      if (old[oldWords[i].start + k] === chars[w.start + k]) keys[w.start + k] = prev[oldWords[i].start + k].key;
    }
  }

  const ordered = anchors.every((a, i) => i === 0 || a.from.start > anchors[i - 1].from.end);
  if (ordered) {
    const bounds = [{ from: 0, to: 0 }, ...anchors.map((a) => ({ from: a.from.end, to: a.to.end }))];
    const ends = [...anchors.map((a) => ({ from: a.from.start, to: a.to.start })), { from: old.length, to: chars.length }];
    bounds.forEach((b, g) => {
      const pairs = edges(old.slice(b.from, ends[g].from), chars.slice(b.to, ends[g].to));
      for (const [i, j] of pairs) keys[b.to + j] = prev[b.from + i].key;
    });
  }

  return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
}

const NUMERIC = /^[^\p{L}]*\d[^\p{L}]*$/u;
const numeric = (text: string) => NUMERIC.test(text);

const NUMBER = /[-\u2212]?\d[\d,.]*/;

function value(text: string) {
  const match = text.match(NUMBER);
  return match ? parseFloat(match[0].replace("\u2212", "-").replace(/,/g, "")) : NaN;
}

function direction(from: string, to: string) {
  const delta = value(to) - value(from);
  return Number.isNaN(delta) ? 0 : Math.sign(delta);
}

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

function translateX(el: Element) {
  const transform = getComputedStyle(el).transform;
  return transform && transform !== "none" ? new DOMMatrixReadOnly(transform).m41 : 0;
}

function measureText(row: HTMLElement, text: string, glyphs: Glyph[]): Layout {
  const node = row.firstChild;
  const origin = row.getBoundingClientRect().left;
  const lefts = new Map<string, number>();
  let width = 0;
  if (node?.nodeType === Node.TEXT_NODE) {
    const range = document.createRange();
    let offset = 0;
    for (const g of glyphs) {
      range.setStart(node, offset);
      range.setEnd(node, (offset += g.char.length));
      const box = range.getBoundingClientRect();
      lefts.set(g.key, box.left - origin);
      width = Math.max(width, box.right - origin);
    }
  }
  return { text, glyphs, lefts, width };
}

export function TextMorph({ children, className }: { children: string; className?: string }) {
  const [shown, setShown] = useState(children);
  const [state, setState] = useState(() => ({ generation: 0, glyphs: toGlyphs(null, children, 0) }));
  if (shown !== children) {
    setShown(children);
    setState((prev) => ({ generation: prev.generation + 1, glyphs: toGlyphs(prev.glyphs, children, prev.generation + 1) }));
  }
  const { glyphs } = state;
  // Plain text until the label first changes.
  const split = state.generation > 0;
  const rowRef = useRef<HTMLSpanElement>(null);
  const ghostsRef = useRef<HTMLSpanElement>(null);
  const layout = useRef<Layout | null>(null);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const ghosts = ghostsRef.current;
    if (!row || !ghosts) return;

    if (!split) {
      layout.current = measureText(row, children, glyphs);
      return;
    }

    const nodes = new Map<string, HTMLElement>();
    for (const el of row.querySelectorAll<HTMLElement>("[data-glyph]")) nodes.set(el.dataset.glyph!, el);

    const last = layout.current;
    const lefts = new Map(glyphs.map((g) => [g.key, nodes.get(g.key)!.offsetLeft]));
    const tail = nodes.get(glyphs.at(-1)?.key ?? "");
    // Fractional, like the row's own width: offsetWidth rounds, and the
    // animation would end half a pixel short and then snap.
    const width = tail ? tail.getBoundingClientRect().right - row.getBoundingClientRect().left : 0;
    layout.current = { text: children, glyphs, lefts, width };

    if (!last || last.text === children) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ghosts.replaceChildren();
      return;
    }

    // The glide, not the move spring: a spring's overshoot narrows a button
    // past its new width and springs it back, which reads as the control
    // settling after the click. The glide lands once.
    const spring = token(row, "--ui-ease-glide", "cubic-bezier(0.22, 1, 0.36, 1)");
    const easeExit = token(row, "--ui-ease-exit", "cubic-bezier(0.4, 0, 1, 1)");
    const duration = ms(token(row, "--ui-dur-glide", "320ms"));
    const exit = ms(token(row, "--ui-dur-instant", "150ms"));
    // Letters arrive on the plain enter curve: a spring would bounce them
    // up and down, and vertical bounce reads as jitter in a line of text.
    const enter = token(row, "--ui-ease-enter", "cubic-bezier(0.2, 1, 0.3, 1)");

    // If a previous morph is still running, start from where it visibly is.
    const running = row.getAnimations();
    const fromWidth = running.length ? row.getBoundingClientRect().width : last.width;
    running.forEach((a) => a.cancel());
    const fade = Math.min(16, Math.abs(width - fromWidth));
    row.dataset.morphing = "";
    const grow = row.animate(
      { width: [`${fromWidth}px`, `${width}px`], ["--morph-fade" as string]: [`${fade}px`, "0px"] },
      { duration, easing: spring },
    );
    grow.finished.then(
      () => delete row.dataset.morphing,
      () => {}, // cancelled by a newer morph, which owns the flag now
    );

    const dir = direction(last.text, children) || 1;
    // A small rise with a soft blur: the change reads, the line holds still.
    const enterFrom = `translateY(${0.08 * dir}em)`;
    const leaveTo = `translateY(${-0.08 * dir}em)`;

    // Arrivals wait for leaving letters to clear.
    const current = new Set(glyphs.map((g) => g.key));
    const leaving = last.glyphs.some((g) => !current.has(g.key));
    const lead = exit * (leaving ? 0.85 : 0.4);
    // Arrivals finish with the width, never after it: each starts once the
    // leaving letters clear, a little after the one before, and is timed to
    // land on the same frame the glide does.
    const arriving = glyphs.filter((g) => !last.lefts.has(g.key)).length;
    const stagger = Math.min(15, (duration - lead - 120) / Math.max(1, arriving));
    let entering = 0;
    for (const g of glyphs) {
      const el = nodes.get(g.key)!;
      const before = last.lefts.get(g.key);
      if (before === undefined) {
        const delay = lead + entering++ * stagger;
        el.animate(
          {
            opacity: [0, 1],
            transform: [enterFrom, "none"],
            filter: ["blur(2px)", "none"],
          },
          { duration: Math.max(120, duration - delay), easing: enter, delay, fill: "backwards" },
        );
        continue;
      }
      // FLIP from where the letter is on screen now.
      const offset = before + translateX(el) - lefts.get(g.key)!;
      el.getAnimations().forEach((a) => a.cancel());
      if (Math.abs(offset) > 0.5) {
        el.animate({ transform: [`translateX(${offset}px)`, "none"] }, { duration, easing: spring });
      }
    }

    // Ghosts live in a layer React never renders into.
    const kept = new Set(glyphs.map((g) => g.key));
    for (const g of last.glyphs) {
      if (kept.has(g.key)) continue;
      const ghost = document.createElement("span");
      ghost.className = styles.ghost;
      ghost.textContent = g.char;
      ghost.style.left = `${last.lefts.get(g.key)}px`;
      ghosts.append(ghost);
      const fade = ghost.animate(
        {
          opacity: [1, 0],
          transform: ["none", leaveTo],
          filter: ["none", "blur(2px)"],
        },
        { duration: exit, easing: easeExit, fill: "forwards" },
      );
      fade.finished.then(
        () => ghost.remove(),
        () => ghost.remove(),
      );
    }
  }, [children, glyphs, split]);

  return (
    // The letter row must run in the label's own direction.
    <span className={className ? `${styles.root} ${className}` : styles.root} dir="auto">
      <span className={styles.label}>{children}</span>
      <span ref={rowRef} className={styles.row} aria-hidden="true">
        {split
          ? glyphs.map((g) => (
              <span key={g.key} data-glyph={g.key} className={styles.glyph}>
                {g.char}
              </span>
            ))
          : children}
        <span ref={ghostsRef} className={styles.ghosts} />
      </span>
    </span>
  );
}

@layer theme, base, components, utilities;

.field {
  composes: field from "../field/field.module.css";
}

.label {
  composes: label from "../field/field.module.css";
}

/* ---------- Calendar ---------- */
.popup {
  composes: popup from "../listbox/listbox.module.css";
}

.panel {
  composes: panel from "../listbox/listbox.module.css";
}

.nav {
  composes: inset from "../field/field.module.css";
}

@layer components {
  .field {
    justify-items: start;
  }

  /* ---------- Field ---------- */

  .trigger {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    max-width: 100%;
    height: var(--ui-control-md);
    padding-inline: var(--ui-space-3);
    border: 0;
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / 1 var(--ui-font-sans);
    text-align: start;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      box-shadow var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .trigger[data-placeholder] .value {
    color: var(--ui-subtle);
  }

  .icon {
    color: var(--ui-muted);
    pointer-events: none;
  }

  @media (hover: hover) {
    .trigger:hover:not(:disabled, [data-popup-open], :focus-visible, [data-invalid]) {
      box-shadow:
        inset 0 0 0 var(--ui-hairline) var(--ui-field-focus);
    }
  }

  .trigger:active:not(:disabled) {
    background: var(--ui-fill-solid);
    transition-duration: var(--ui-dur-press);
  }

  .trigger:focus-visible,
  .trigger[data-popup-open] {
    outline: none;
    box-shadow: inset 0 0 0 1px var(--ui-field-focus);
    transition-duration: 0s;
  }

  .trigger[data-invalid] {
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-danger);
  }

  .trigger[data-invalid]:is(:focus-visible, [data-popup-open]) {
    box-shadow: inset 0 0 0 1px var(--ui-danger);
  }

  .trigger:disabled {
    opacity: 0.5;
    cursor: default;
  }

  .panel {
    --panel-pad: var(--ui-space-3);
    --inner-radius: calc(var(--ui-radius-lg) - var(--panel-pad));
    --cell: 36px;
    --weekday-height: var(--ui-control-sm);
    --panel-radius: var(--ui-radius-lg);
    display: grid;
    gap: var(--ui-space-2);
    padding: var(--panel-pad);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    /* A block-sized popover enters like a dialog: the fade answers on the fast
       step, the scale and the blur settle on the base one. */
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-base) var(--ui-ease-enter),
      filter var(--ui-dur-base) var(--ui-ease-enter);
  }

  /* Leaves one step faster on the exit curve (from the listbox panel). */

  @media (pointer: coarse) {
    .panel {
      --cell: 40px;
    }
  }

  .header {
    display: grid;
    grid-template-columns: var(--ui-control-sm) 1fr var(--ui-control-sm);
    align-items: center;
  }

  .title {
    display: grid;
    justify-items: center;
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    text-align: center;
  }

  .titleText {
    font-variant-numeric: tabular-nums;
  }

  /* Doubled so it outranks the composed inset rule in any stylesheet order. */
  .nav.nav {
    border-radius: var(--inner-radius);
  }

  .day::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .nav[aria-disabled] {
    opacity: 0.35;
  }

  /* ---------- Grid ---------- */

  /* Runs out to the panel's edges, so a sliding month fades through the
     panel's padding instead of meeting a hard cut. At rest every day sits
     inside the padding, clear of the fade. */
  .stage {
    position: relative;
    overflow: hidden;
    margin-inline: calc(var(--panel-pad) * -1);
    padding-inline: var(--panel-pad);
    mask-image: linear-gradient(
      to right,
      transparent,
      #000 var(--panel-pad),
      #000 calc(100% - var(--panel-pad)),
      transparent
    );
  }

  .grid {
    border-collapse: collapse;
    border-spacing: 0;
    table-layout: fixed;
    width: calc(var(--cell) * 7);
  }

  .weekday {
    height: var(--weekday-height);
    padding: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-regular);
    line-height: var(--ui-leading-sm);
    text-align: center;
  }

  .cell {
    width: var(--cell);
    height: var(--cell);
    padding: 0;
  }

  .day {
    position: relative;
    display: grid;
    place-items: center;
    width: var(--cell);
    height: var(--cell);
    padding: 0;
    border: 0;
    border-radius: var(--inner-radius);
    background: none;
    color: var(--ui-foreground);
    font: inherit;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .day > * {
    position: relative;
  }

  @media (hover: hover) {
    .day:hover:not([aria-disabled], [data-selected])::before {
      background: var(--ui-fill-strong);
    }
  }

  .day:active:not([aria-disabled])::before {
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .day:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .day[data-today]::after {
    content: "";
    position: absolute;
    bottom: 6px;
    left: 50%;
    width: 10px;
    height: 1.5px;
    margin-left: -5px;
    border-radius: 1px;
    background: currentColor;
  }

  .day[data-selected] {
    color: var(--ui-on-accent);
    font-weight: var(--ui-weight-medium);
  }

  .day[data-selected]::before {
    background: var(--ui-accent);
  }

  .day[aria-disabled] {
    color: var(--ui-subtle);
    text-decoration: line-through;
    text-decoration-color: color-mix(in oklch, currentColor 50%, transparent);
    cursor: default;
  }

  .cell[data-between] {
    background: var(--ui-fill-strong);
  }

  .cell[data-edge="start"] {
    background: linear-gradient(to right, transparent 50%, var(--ui-fill-strong) 50%);
  }

  .cell[data-edge="end"] {
    background: linear-gradient(to left, transparent 50%, var(--ui-fill-strong) 50%);
  }

  :is([dir="rtl"]) .cell[data-edge="start"] {
    background: linear-gradient(to left, transparent 50%, var(--ui-fill-strong) 50%);
  }

  :is([dir="rtl"]) .cell[data-edge="end"] {
    background: linear-gradient(to right, transparent 50%, var(--ui-fill-strong) 50%);
  }

  .cell[data-between]:first-child,
  .cell[data-between]:not(.cell:is([data-between], [data-edge]) + .cell) {
    border-start-start-radius: var(--inner-radius);
    border-end-start-radius: var(--inner-radius);
  }

  .cell[data-between]:last-child,
  .cell[data-between]:has(+ .cell:not([data-between], [data-edge])) {
    border-start-end-radius: var(--inner-radius);
    border-end-end-radius: var(--inner-radius);
  }

  .day:not([data-selected]):is(.cell[data-between] .day):hover::before {
    background: var(--ui-fill);
  }

  /* ---------- Month slide ---------- */

  /* The new month comes from the side you moved toward and the old one leaves
     the other way: both slide 20px on the glide spring, so neither swings
     past its place. The old one is gone on the instant step before the new
     one is more than faint, so the digits never read on top of each other.
     The weekday row and the panel hold still; the title morphs (TextMorph). */
  .panel {
    --slide: 20px;
  }

  .weeks[data-dir] {
    animation:
      date-in-x var(--ui-dur-glide) var(--ui-ease-glide),
      date-in-fade var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  .leaving {
    position: absolute;
    inset-block-start: var(--weekday-height);
    inset-inline-start: var(--panel-pad);
    pointer-events: none;
    animation:
      date-out-fade var(--ui-dur-instant) var(--ui-ease-color) forwards,
      date-out-x var(--ui-dur-glide) var(--ui-ease-glide) forwards;
  }

  .panel [data-dir="-1"],
  .panel [data-leaving="-1"] {
    --dir: -1;
  }

  :is([dir="rtl"]) .panel {
    --flip: -1;
  }

  @keyframes date-in-x {
    from {
      translate: calc(var(--dir, 1) * var(--flip, 1) * var(--slide)) 0;
    }
  }

  @keyframes date-in-fade {
    from {
      opacity: 0;
    }
  }

  @keyframes date-out-x {
    from {
      translate: var(--from-x, 0px) 0;
    }
    to {
      translate: calc(var(--dir, 1) * var(--flip, 1) * var(--slide) * -1) 0;
    }
  }

  @keyframes date-out-fade {
    from {
      opacity: var(--from-opacity, 1);
    }
    to {
      opacity: 0;
    }
  }

  .status {
    margin: 0;
    padding-inline: var(--ui-space-1);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-align: center;
  }

  /* Reduced motion: the months crossfade in place and the panel only fades. */
  @media (prefers-reduced-motion: reduce) {
    /* Doubled to outrank the listbox panel's own states in any stylesheet order. */
    .panel.panel {
      transition-property: opacity;
    }
    .panel.panel:is([data-starting-style], [data-ending-style]) {
      scale: none;
      filter: none;
    }
    .weeks[data-dir] {
      animation: date-in-fade var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
    }
    .leaving {
      animation: date-out-fade var(--ui-dur-instant) var(--ui-ease-color) forwards;
    }
    .day:active:not([aria-disabled])::before {
      scale: none;
    }
  }
}

"use client";

import {
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from "react";
import { Popover } from "@base-ui/react/popover";
import { FieldMessage } from "../field/field";
import { Icon } from "../icons/icons";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./date-picker.module.css";

/* ISO day strings, worked on as UTC midnights so no time zone or DST change moves a day. */

export type DateRange = { start: string; end: string };

type Common = {
  label: string;
  /** Earliest choosable day, as "YYYY-MM-DD". */
  min?: string;
  /** Latest choosable day, as "YYYY-MM-DD". */
  max?: string;
  /** Days that can't be chosen. */
  isDateDisabled?: (date: string) => boolean;
  /** 0 is Sunday, 1 is Monday. Defaults to Sunday. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  locale?: string;
  placeholder?: string;
  hint?: string;
  /** An error from outside, such as the server. */
  error?: string | null;
  required?: boolean;
  disabled?: boolean;
  id?: string;
  className?: string;
  ref?: Ref<HTMLButtonElement>;
};

type SingleProps = Common & {
  mode?: "single";
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  /** Return a fix-it message, or null. Runs when the field is left. */
  validate?: (value: string | null) => string | null;
  name?: string;
};

type RangeProps = Common & {
  mode: "range";
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onValueChange?: (value: DateRange | null) => void;
  validate?: (value: DateRange | null) => string | null;
  /** Form names for the two ends. */
  name?: { start: string; end: string };
};

type DatePickerProps = SingleProps | RangeProps;

type Ymd = { y: number; m: number };
/** A month on its way out, starting from where the live one visibly was. */
type Leaving = { view: Ymd; dir: 1 | -1; key: number; opacity: number; x: number };

const DAY = 86_400_000;
const toTime = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  return Date.UTC(y, m - 1, d);
};
const toIso = (t: number) => new Date(t).toISOString().slice(0, 10);
const isIso = (s: unknown): s is string => typeof s === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s);
const viewOf = (iso: string): Ymd => {
  const d = new Date(toTime(iso));
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() };
};
const sameView = (a: Ymd, b: Ymd) => a.y === b.y && a.m === b.m;
const viewIndex = (v: Ymd) => v.y * 12 + v.m;

function addMonths(iso: string, by: number) {
  const d = new Date(toTime(iso));
  const target = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + by, 1));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
  target.setUTCDate(Math.min(d.getUTCDate(), last));
  return toIso(target.getTime());
}

const addDays = (iso: string, by: number) => toIso(toTime(iso) + by * DAY);

function todayIso() {
  const now = new Date();
  return toIso(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
}

/** Always six weeks, so the grid never changes height. */
function weeks(view: Ymd, weekStart: number) {
  const first = Date.UTC(view.y, view.m, 1);
  const offset = (new Date(first).getUTCDay() - weekStart + 7) % 7;
  const start = first - offset * DAY;
  return Array.from({ length: 6 }, (_, w) =>
    Array.from({ length: 7 }, (_, d) => {
      const t = start + (w * 7 + d) * DAY;
      return { iso: toIso(t), inMonth: new Date(t).getUTCMonth() === view.m, day: new Date(t).getUTCDate() };
    }),
  );
}

function Weeks({ dir, children }: { dir?: 1 | -1; children: ReactNode }) {
  return (
    <tbody className={styles.weeks} data-dir={dir}>
      {children}
    </tbody>
  );
}

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === "function") ref(value);
  else if (ref) ref.current = value;
}

/** A date field that opens a WAI-ARIA date picker dialog, with an optional range mode. */
export function DatePicker(props: DatePickerProps) {
  const {
    label,
    min,
    max,
    isDateDisabled,
    weekStartsOn = 0,
    locale,
    placeholder = props.mode === "range" ? "Choose dates" : "Choose a date",
    hint,
    error: externalError,
    required,
    disabled = false,
    id,
    className,
    ref,
  } = props;
  const range = props.mode === "range";

  const baseId = useId();
  const triggerId = id ?? `${baseId}-trigger`;
  const labelId = `${baseId}-label`;
  const dialogId = `${baseId}-dialog`;
  const titleId = `${baseId}-title`;
  const messageId = `${baseId}-message`;

  const [uncontrolled, setUncontrolled] = useState<string | DateRange | null>(props.defaultValue ?? null);
  const value = (props.value !== undefined ? props.value : uncontrolled) as string | DateRange | null;
  const single = !range && isIso(value) ? value : null;
  const rangeValue = range && value && typeof value === "object" && isIso(value.start) && isIso(value.end) ? value : null;

  function commit(next: string | DateRange | null) {
    if (props.value === undefined) setUncontrolled(next);
    (props.onValueChange as ((v: unknown) => void) | undefined)?.(next);
    if (localError) setLocalError((props.validate as ((v: unknown) => string | null) | undefined)?.(next) ?? null);
  }

  const fmt = useMemo(
    () => ({
      field: new Intl.DateTimeFormat(locale, { weekday: "short", month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }),
      rangeField: new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }),
      title: new Intl.DateTimeFormat(locale, { month: "long", year: "numeric", timeZone: "UTC" }),
      full: new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }),
      weekday: new Intl.DateTimeFormat(locale, { weekday: "short", timeZone: "UTC" }),
      weekdayLong: new Intl.DateTimeFormat(locale, { weekday: "long", timeZone: "UTC" }),
      day: new Intl.NumberFormat(locale),
    }),
    [locale],
  );

  // Server and browser ICU differ on thin and no-break spaces; plain ones hydrate cleanly.
  const display = (
    single
      ? fmt.field.format(toTime(single))
      : rangeValue
        ? fmt.rangeField.formatRange(toTime(rangeValue.start), toTime(rangeValue.end))
        : placeholder
  ).replace(/[\u2009\u202f\u00a0]/g, " ");

  const [localError, setLocalError] = useState<string | null>(null);
  const error = externalError ?? localError;
  const hasMessage = Boolean(hint || props.validate || required || externalError !== undefined);

  function runValidate(next: string | DateRange | null) {
    if (props.validate) return (props.validate as (v: unknown) => string | null)(next);
    if (required && !next) return range ? "Choose a start and end date" : "Choose a date";
    return null;
  }

  const [open, setOpen] = useState(false);
  const [focused, setFocused] = useState<string>("2000-01-01");
  const [view, setView] = useState<Ymd>({ y: 2000, m: 0 });
  const [today, setToday] = useState<string | null>(null);
  // Range: the first day pressed, waiting for the second.
  const [anchor, setAnchor] = useState<string | null>(null);
  const [hovered, setHovered] = useState<string | null>(null);
  // Months on their way out. More than one only when months are paged faster than they fade.
  const [leaving, setLeaving] = useState<Leaving[]>([]);
  // 0 until the month first changes, so the grid doesn't slide in as the calendar opens.
  const [dir, setDir] = useState<0 | 1 | -1>(0);
  const [slides, setSlides] = useState(0);

  const triggerRef = useRef<HTMLButtonElement>(null);
  const popupRef = useRef<HTMLDivElement>(null);
  // Floating content portals into the nearest themed subtree, so it keeps its tokens.
  const [container, setContainer] = useState<HTMLElement | null>(null);
  const gridRef = useRef<HTMLTableElement>(null);
  const moveFocus = useRef(false);

  const inRange = (iso: string) => (!min || iso >= min) && (!max || iso <= max);
  const choosable = (iso: string) => inRange(iso) && !isDateDisabled?.(iso);

  function clampToBounds(iso: string) {
    if (min && iso < min) return min;
    if (max && iso > max) return max;
    return iso;
  }

  function showView(next: Ymd) {
    if (sameView(next, view)) return;
    const d = viewIndex(next) > viewIndex(view) ? 1 : -1;
    // Paged again mid-slide: the month leaves from where it is, not from rest.
    const live = gridRef.current?.tBodies[0];
    const style = live ? getComputedStyle(live) : null;
    const opacity = style ? parseFloat(style.opacity) : 1;
    const x = style && style.translate !== "none" ? parseFloat(style.translate) || 0 : 0;
    const key = slides + 1;
    setLeaving((list) => [...list.slice(-1), { view, dir: d, key, opacity, x }]);
    setSlides(key);
    setDir(d);
    setView(next);
  }

  function focusDate(iso: string, keyboard: boolean) {
    const next = clampToBounds(iso);
    setFocused(next);
    showView(viewOf(next));
    if (keyboard) moveFocus.current = true;
  }

  function openCalendar() {
    if (disabled) return;
    const now = todayIso();
    setToday(now);
    const start = single ?? rangeValue?.start ?? clampToBounds(now);
    setFocused(start);
    setView(viewOf(start));
    setLeaving([]);
    setDir(0);
    setAnchor(null);
    setHovered(null);
    moveFocus.current = true;
    setOpen(true);
  }

  // Base UI's Popover returns focus to the trigger when focus was inside the calendar.
  function close() {
    setOpen(false);
    setAnchor(null);
    setHovered(null);
  }

  function choose(iso: string) {
    if (!choosable(iso)) return;
    if (!range) {
      commit(iso);
      close();
      return;
    }
    if (!anchor) {
      setAnchor(iso);
      setFocused(iso);
      return;
    }
    const [start, end] = anchor <= iso ? [anchor, iso] : [iso, anchor];
    // A range can't run across a day that can't be chosen.
    for (let t = toTime(start); t <= toTime(end); t += DAY) {
      if (!choosable(toIso(t))) {
        setAnchor(iso);
        setFocused(iso);
        return;
      }
    }
    commit({ start, end });
    close();
  }

  useLayoutEffect(() => {
    if (!open || !moveFocus.current) return;
    const button = gridRef.current?.querySelector<HTMLButtonElement>(`[data-iso="${focused}"]`);
    if (!button) return;
    moveFocus.current = false;
    button.focus({ preventScroll: true });
  });

  function onGridKeyDown(event: KeyboardEvent<HTMLTableElement>) {
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
    const weekPos = (new Date(toTime(focused)).getUTCDay() - weekStartsOn + 7) % 7;
    let next: string | null = null;
    switch (event.key) {
      case "ArrowRight":
        next = addDays(focused, rtl ? -1 : 1);
        break;
      case "ArrowLeft":
        next = addDays(focused, rtl ? 1 : -1);
        break;
      case "ArrowDown":
        next = addDays(focused, 7);
        break;
      case "ArrowUp":
        next = addDays(focused, -7);
        break;
      case "Home":
        next = addDays(focused, -weekPos);
        break;
      case "End":
        next = addDays(focused, 6 - weekPos);
        break;
      case "PageDown":
        next = addMonths(focused, event.shiftKey ? 12 : 1);
        break;
      case "PageUp":
        next = addMonths(focused, event.shiftKey ? -12 : -1);
        break;
      case "Enter":
      case " ":
        event.preventDefault();
        choose(focused);
        return;
      default:
        return;
    }
    event.preventDefault();
    focusDate(next, true);
    if (range && anchor) setHovered(clampToBounds(next));
  }

  // Month buttons at a limit use aria-disabled, so they keep focus and Escape still works.
  // Tab cycles inside the calendar; Base UI closes it on Escape.
  function onDialogKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Tab") return;
    const stops = [...(popupRef.current?.querySelectorAll<HTMLElement>("button[tabindex='0'], button:not([tabindex], [aria-disabled])") ?? [])];
    if (stops.length === 0) return;
    const at = stops.indexOf(document.activeElement as HTMLElement);
    const to = event.shiftKey ? (at <= 0 ? stops.length - 1 : at - 1) : at === stops.length - 1 ? 0 : at + 1;
    event.preventDefault();
    stops[to].focus();
  }

  const weekdayNames = Array.from({ length: 7 }, (_, i) => {
    // 2023-01-01 was a Sunday.
    const t = Date.UTC(2023, 0, 1 + ((weekStartsOn + i) % 7));
    return { short: fmt.weekday.format(t), long: fmt.weekdayLong.format(t) };
  });

  const nextMonth = addMonths(`${view.y}-${String(view.m + 1).padStart(2, "0")}-01`, 1);
  const lastOfPrev = addDays(`${view.y}-${String(view.m + 1).padStart(2, "0")}-01`, -1);
  const canPrev = !min || lastOfPrev >= min;
  const canNext = !max || nextMonth <= max;

  const band = (() => {
    if (range && anchor) {
      const other = hovered ?? anchor;
      return anchor <= other ? { start: anchor, end: other } : { start: other, end: anchor };
    }
    return rangeValue;
  })();

  function renderGrid(v: Ymd, live: boolean) {
    return (
      <>
        {weeks(v, weekStartsOn).map((week) => (
          <tr key={week[0].iso}>
            {week.map((cell) => {
              if (!cell.inMonth) return <td key={cell.iso} className={styles.cell} />;
              const can = choosable(cell.iso);
              const selected = single === cell.iso || (band !== null && (cell.iso === band.start || cell.iso === band.end));
              const between = band !== null && cell.iso > band.start && cell.iso < band.end;
              const edge = band && band.start !== band.end ? (cell.iso === band.start ? "start" : cell.iso === band.end ? "end" : undefined) : undefined;
              return (
                <td
                  key={cell.iso}
                  role="gridcell"
                  className={styles.cell}
                  aria-selected={live ? selected || between || undefined : undefined}
                  data-between={between || undefined}
                  data-edge={edge}
                >
                  <button
                    type="button"
                    className={styles.day}
                    data-iso={live ? cell.iso : undefined}
                    data-selected={selected || undefined}
                    data-today={cell.iso === today || undefined}
                    tabIndex={live && cell.iso === focused ? 0 : -1}
                    aria-label={fmt.full.format(toTime(cell.iso))}
                    aria-current={cell.iso === today ? "date" : undefined}
                    aria-disabled={!can || undefined}
                    onClick={live ? () => choose(cell.iso) : undefined}
                    onPointerEnter={live && range && anchor ? () => setHovered(cell.iso) : undefined}
                    onFocus={live ? () => setFocused(cell.iso) : undefined}
                  >
                    <span>{fmt.day.format(cell.day)}</span>
                  </button>
                </td>
              );
            })}
          </tr>
        ))}
      </>
    );
  }

  const title = (v: Ymd) => fmt.title.format(Date.UTC(v.y, v.m, 1));

  const formValue = (
    <>
      {!range && typeof props.name === "string" && <input type="hidden" name={props.name} value={single ?? ""} />}
      {range && props.name && typeof props.name === "object" && (
        <>
          <input type="hidden" name={props.name.start} value={rangeValue?.start ?? ""} />
          <input type="hidden" name={props.name.end} value={rangeValue?.end ?? ""} />
        </>
      )}
    </>
  );

  return (
    <div className={className ? `${styles.field} ${className}` : styles.field}>
      <label
        id={labelId}
        className={styles.label}
        // Like a native control, the label focuses the field.
        onClick={() => triggerRef.current?.focus()}
      >
        {label}
      </label>
      <Popover.Root
        open={open}
        onOpenChange={(next) => (next ? openCalendar() : close())}
        triggerId={triggerId}
      >
        <Popover.Trigger
          ref={(node: HTMLButtonElement | null) => {
            triggerRef.current = node;
            setContainer(node?.closest<HTMLElement>("[data-theme]") ?? null);
            assignRef(ref, node);
          }}
          id={triggerId}
          className={styles.trigger}
          disabled={disabled}
          aria-labelledby={`${labelId} ${triggerId}`}
          // A button can't be aria-invalid; the error is read from the message.
          aria-describedby={hasMessage && (error || hint) ? messageId : undefined}
          data-invalid={error ? "" : undefined}
          data-placeholder={single || rangeValue ? undefined : ""}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown" && !open) {
              event.preventDefault();
              openCalendar();
            }
          }}
          onBlur={(event) => {
            const next = event.relatedTarget as Node | null;
            if (next && popupRef.current?.contains(next)) return;
            if (!open) setLocalError(runValidate(value));
          }}
        >
          <TextMorph className={styles.value}>{display}</TextMorph>
          <Icon name="calendar" className={styles.icon} />
        </Popover.Trigger>
        {formValue}
        {hasMessage && <FieldMessage id={messageId} hint={hint} error={error} />}
        <Popover.Portal container={container ?? undefined}>
          <Popover.Positioner className={styles.popup} side="bottom" align="start" sideOffset={8} collisionPadding={8}>
            <Popover.Popup
              ref={popupRef}
              id={dialogId}
              className={styles.panel}
              // The day to start on, not the first button in the header.
              initialFocus={() => gridRef.current?.querySelector<HTMLElement>(`[data-iso="${focused}"]`) ?? true}
              onKeyDown={onDialogKeyDown}
            >
              <div className={styles.header}>
                <button
                  type="button"
                  className={styles.nav}
                  aria-label="Previous month"
                  aria-disabled={!canPrev || undefined}
                  onClick={() => canPrev && focusDate(addMonths(focused, -1), false)}
                >
                  <Icon name="chevron-left" />
                </button>
                <Popover.Title id={titleId} className={styles.title} aria-live="polite">
                  <TextMorph className={styles.titleText}>{title(view)}</TextMorph>
                </Popover.Title>
                <button
                  type="button"
                  className={styles.nav}
                  aria-label="Next month"
                  aria-disabled={!canNext || undefined}
                  onClick={() => canNext && focusDate(addMonths(focused, 1), false)}
                >
                  <Icon name="chevron-right" />
                </button>
              </div>
              <div className={styles.stage}>
                <table
                  ref={gridRef}
                  role="grid"
                  aria-labelledby={titleId}
                  className={styles.grid}
                  onKeyDown={onGridKeyDown}
                  onPointerLeave={() => setHovered(null)}
                >
                  <thead>
                    <tr>
                      {weekdayNames.map((w) => (
                        <th key={w.long} scope="col" abbr={w.long} className={styles.weekday}>
                          {w.short}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <Weeks key={`w${slides}`} dir={dir || undefined}>
                    {renderGrid(view, true)}
                  </Weeks>
                </table>
                {leaving.map((out) => (
                  <table
                    key={`leaving${out.key}`}
                    className={`${styles.grid} ${styles.leaving}`}
                    data-leaving={out.dir}
                    style={{ "--from-opacity": out.opacity, "--from-x": `${out.x}px` } as CSSProperties}
                    aria-hidden="true"
                    inert
                    // Gone once it has faded; its slide has nothing left to show.
                    onAnimationEnd={(e) => {
                      if (e.target === e.currentTarget) setLeaving((list) => list.filter((l) => l.key !== out.key));
                    }}
                  >
                    <tbody>{renderGrid(out.view, false)}</tbody>
                  </table>
                ))}
              </div>
              {range && (
                <p className={styles.status} aria-live="polite">
                  {anchor ? "Now choose the last day" : "Choose the first day"}
                </p>
              )}
            </Popover.Popup>
          </Popover.Positioner>
        </Popover.Portal>
      </Popover.Root>
    </div>
  );
}
